\"sold\" };\n            _response = _petApiHelper.SendPutRequest(_scenarioContext[\"Endpoint\"].ToString(), updatedPetDetails);\n            Log.Information(\"PUT request sent with payload: {Payload}\", JsonConvert.SerializeObject(updatedPetDetails));\n        }\n\n        [When(@\"I send a DELETE request for petId \"\"(.*)\"\"\")]\n        public void WhenISendADeleteRequestForPetId(string petId)\n        {\n            _response = _petApiHelper.SendDeleteRequest(_scenarioContext[\"Endpoint\"].ToString().Replace(\"{petId}\", petId));\n            Log.Information(\"DELETE request sent for petId: {PetId}\", petId);\n        }\n\n        [Then(@\"the response status code should be 200\")]\n        public void ThenTheResponseStatusCodeShould